//! The hybrid import analyzer (imports-are-derived-from-the-composes-graph) — parse a record's
//! TypeScript import statements and structure each into an [`ImportSpec`], classifying its `from`
//! against the record universe. It does NOT rewrite `code` (that is the migration slice) and it does
//! NOT emit (that is the materializer slice); it is the shared core both consume.
//!
//! Classification of an import's `from`:
//!   - RECORD-INTERNAL: `from` is some record's `provides` specifier → a derivable [`ImportSpec`]
//!     (a rename/move of that record re-emits this import with zero edits here).
//!   - EXTERNAL: an npm package / `node:*` / the `@data/*` alias — anything that is neither a record
//!     `provides` nor a bare `@/…` path → a derivable [`ImportSpec`], emitted verbatim.
//!   - FLOOR FILE: `@/…` that resolves to NO record `provides` (the legitimate-floor modules like
//!     `@/store`, `TerminalHost`) → NOT derivable; it stays hand-written in `code`. Reported in
//!     [`AnalyzedImports::floor`] so the migration leaves those lines alone.
//!
//! WHY hybrid, not pure inference: `import type` (~13% of imports here), `import * as X` (~14%,
//! undecidable from usage), default and side-effect imports all carry shape that cannot be recovered
//! from symbol usage alone — so the analyzer captures the shape explicitly rather than guessing it.
//!
//! WHY tree-sitter for extraction: a record's `code` is full of doc comments that say the word
//! "import" (this module's own header does). Scanning raw text would match them. tree-sitter hands us
//! the real `import_statement` nodes — comment- and string-safe — and each node's verbatim text is a
//! single clean statement a small text parser can finish without a lexer of its own.

use crate::ImportSpec;
use std::collections::HashSet;
use tree_sitter::Parser;

// Pure leaf free-functions, each its own record (decompose-bsc-graph-fat-records).
pub use analyze_imports::analyze_imports;
pub(crate) use import_statements::import_statements;
pub(crate) use parse_statement::parse_statement;
pub(crate) use parse_clause::parse_clause;
pub(crate) use normalize_ws::normalize_ws;
pub(crate) use quoted::quoted;
pub(crate) use quoted_last::quoted_last;
pub(crate) use to_fmt::to_fmt;
pub(crate) use from_fmt::from_fmt;
pub(crate) use import_spans::import_spans;
pub use normalize_code::normalize_code;
pub use migrate_code::migrate_code;

/// The outcome of analyzing one record's imports.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct AnalyzedImports {
    /// Derivable — belongs in [`crate::AlgoImpl::imports`]: record-internal + external entries.
    pub derived: Vec<ImportSpec>,
    /// `@/…` imports resolving to no record `provides` — floor FILES; they stay hand-written in `code`.
    pub floor: Vec<ImportSpec>,
}

/// The outcome of [`normalize_code`].
pub struct NormalizedImports {
    /// The rewritten module source: derivable imports canonicalized into one block at the top.
    pub code: String,
    /// The specs that belong in the record's `imports` field (record-internal + external).
    pub derived: Vec<ImportSpec>,
}

#[cfg(test)]
mod tests {
    use super::*;

    fn universe() -> HashSet<String> {
        // The record `provides` specifiers the sample imports resolve against.
        [
            "@/features/glance/lib/glanceData",
            "@/features/glance/lib/featureNodes",
            "@/app/console/useConsolePumps",
            "@/shared/lib/session/sessionRoles",
            "@/features/algorithms/lib/knowledge",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect()
    }

    fn one<'a>(a: &'a AnalyzedImports, from: &str) -> &'a ImportSpec {
        a.derived.iter().chain(a.floor.iter()).find(|s| s.from == from).expect("import present")
    }

    #[test]
    fn record_internal_named_is_derived_with_its_symbols() {
        let code = "import { renderGraph, layout } from \"@/features/glance/lib/glanceData\";\n";
        let a = analyze_imports(code, &universe());
        assert_eq!(a.floor.len(), 0);
        let s = one(&a, "@/features/glance/lib/glanceData");
        assert_eq!(s.kind, "named");
        assert!(!s.type_only);
        assert_eq!(s.symbols, vec!["renderGraph".to_string(), "layout".to_string()]);
    }

    #[test]
    fn type_only_is_captured() {
        let code = "import type { Workspace } from \"@/shared/lib/session/sessionRoles\";";
        let a = analyze_imports(code, &universe());
        let s = one(&a, "@/shared/lib/session/sessionRoles");
        assert!(s.type_only, "import type must set typeOnly");
        assert_eq!(s.kind, "named");
    }

    #[test]
    fn namespace_import_records_kind_and_binding() {
        // algorithms-graph-platform's `import * as X` shape — undecidable from usage, must be captured.
        let code = "import * as Knowledge from \"@/features/algorithms/lib/knowledge\";";
        let a = analyze_imports(code, &universe());
        let s = one(&a, "@/features/algorithms/lib/knowledge");
        assert_eq!(s.kind, "namespace");
        assert_eq!(s.symbols, vec!["Knowledge".to_string()]);
    }

    #[test]
    fn default_and_default_plus_named_split() {
        let a = analyze_imports("import React from \"react\";", &universe());
        assert_eq!(one(&a, "react").kind, "default");
        assert_eq!(one(&a, "react").symbols, vec!["React".to_string()]);

        // `import D, { a, b } from "x"` → two specs sharing the source.
        let b = analyze_imports("import React, { useState, useEffect } from \"react\";", &universe());
        let kinds: Vec<&str> = b.derived.iter().map(|s| s.kind.as_str()).collect();
        assert!(kinds.contains(&"default") && kinds.contains(&"named"), "split into default + named");
    }

    #[test]
    fn external_vs_floor_file_classification() {
        let code = concat!(
            "import { useState } from \"react\";\n",           // external npm
            "import { demo } from \"@data/demo\";\n",           // @data alias → external
            "import { useAppStore } from \"@/store\";\n",       // @/… but NOT a record → floor file
            "import { featureNode } from \"@/features/glance/lib/featureNodes\";\n" // record-internal
        );
        let a = analyze_imports(code, &universe());
        let derived: HashSet<&str> = a.derived.iter().map(|s| s.from.as_str()).collect();
        let floor: HashSet<&str> = a.floor.iter().map(|s| s.from.as_str()).collect();
        assert!(derived.contains("react") && derived.contains("@data/demo"));
        assert!(derived.contains("@/features/glance/lib/featureNodes"));
        assert!(floor.contains("@/store"), "@/store has no record provides → floor, hand-written");
        assert!(!derived.contains("@/store"));
    }

    #[test]
    fn side_effect_import_has_empty_symbols() {
        let a = analyze_imports("import \"@/styles/tokens.css\";", &universe());
        // @/styles/... is not a record → floor
        let s = one(&a, "@/styles/tokens.css");
        assert_eq!(s.kind, "side-effect");
        assert!(s.symbols.is_empty());
    }

    #[test]
    fn multiline_clause_parses_like_single_line() {
        let code = "import {\n  renderGraph,\n  layout,\n} from \"@/features/glance/lib/glanceData\";\n";
        let a = analyze_imports(code, &universe());
        let s = one(&a, "@/features/glance/lib/glanceData");
        assert_eq!(s.symbols, vec!["renderGraph".to_string(), "layout".to_string()]);
    }

    #[test]
    fn doc_comment_saying_import_is_not_parsed() {
        // The tree-sitter extraction must ignore the word "import" inside a comment / string — this is
        // exactly the false-positive a raw text scan would hit (this crate's own headers do it).
        let code = concat!(
            "// This module used to import from \"@/legacy/thing\" before the refactor.\n",
            "/* import { ghost } from \"@/not/real\" */\n",
            "const s = \"import { x } from 'nope'\";\n",
            "import { real } from \"@/app/console/useConsolePumps\";\n"
        );
        let a = analyze_imports(code, &universe());
        let froms: Vec<&str> = a.derived.iter().chain(a.floor.iter()).map(|s| s.from.as_str()).collect();
        assert_eq!(froms, vec!["@/app/console/useConsolePumps"], "only the real import is seen");
    }

    #[test]
    fn aliases_are_kept_verbatim() {
        let code = "import { foo as bar, baz } from \"@/features/glance/lib/glanceData\";";
        let a = analyze_imports(code, &universe());
        assert_eq!(one(&a, "@/features/glance/lib/glanceData").symbols, vec!["foo as bar".to_string(), "baz".to_string()]);
    }

    // The additive-field contract (imports-are-derived-from-the-composes-graph): the new `imports`
    // field must leave every pre-existing record byte-identical, and a record that carries imports
    // must round-trip preserving typeOnly + kind. This mirrors the sibling `algo_impl_<facet>_is_
    // additive_round_trips` guards in bsc-graph--tests.rs; it fails against the pre-field struct.
    #[test]
    fn imports_field_is_additive_and_round_trips_byte_identically() {
        use crate::AlgoImpl;

        // (a) A record written before this field round-trips with NO `imports` key emitted.
        let bare = serde_json::json!({
            "id": "merge.rs", "tech": "rust", "role": "algorithm", "name": "merge",
            "composes": [], "code": "// merge"
        });
        let im: AlgoImpl = serde_json::from_value(bare.clone()).unwrap();
        assert!(im.imports.is_empty());
        let re = serde_json::to_value(&im).unwrap();
        assert!(re.get("imports").is_none(), "no empty imports key is emitted");
        assert_eq!(re, bare, "a pre-field record round-trips byte-identically");

        // (b) A record carrying derived imports round-trips unchanged. `typeOnly:false` and an empty
        //     `symbols` are OMITTED (skip_serializing_if); `kind` is always present.
        let withimp = serde_json::json!({
            "id": "role-view.rs", "tech": "rust", "role": "algorithm", "name": "role_view",
            "composes": [], "code": "//",
            "imports": [
                { "from": "@/shared/lib/session/sessionRoles", "symbols": ["Role"], "typeOnly": true, "kind": "named" },
                { "from": "react", "symbols": ["React"], "kind": "namespace" },
                { "from": "@/styles/tokens.css", "kind": "named" }
            ]
        });
        let im2: AlgoImpl = serde_json::from_value(withimp.clone()).unwrap();
        assert_eq!(im2.imports.len(), 3);
        assert!(im2.imports[0].type_only && im2.imports[0].kind == "named");
        assert_eq!(im2.imports[1].kind, "namespace");
        assert!(im2.imports[2].symbols.is_empty() && !im2.imports[2].type_only);
        assert_eq!(serde_json::to_value(&im2).unwrap(), withimp, "the imports facet round-trips byte-identically");

        // (c) A bare ImportSpec defaults `kind` to "named" and carries no typeOnly / symbols.
        let spec: ImportSpec = serde_json::from_value(serde_json::json!({ "from": "./x" })).unwrap();
        assert_eq!(spec.kind, "named");
        assert!(!spec.type_only && spec.symbols.is_empty());
    }

    #[test]
    fn normalize_then_migrate_is_byte_parity_by_construction() {
        let u = universe();
        // messy, out-of-order, multi-line: a floor import first, a record import multi-line, an external.
        let code = concat!(
            "// module header\n\n",
            "import { useAppStore } from \"@/store\";\n",
            "import {\n  renderGraph,\n  layout,\n} from \"@/features/glance/lib/glanceData\";\n",
            "import React from \"react\";\n\n",
            "export const x = 1;\n",
        );
        let norm = normalize_code(code, &u);
        let froms: Vec<&str> = norm.derived.iter().map(|s| s.from.as_str()).collect();
        assert!(froms.contains(&"@/features/glance/lib/glanceData") && froms.contains(&"react"));
        assert!(!froms.contains(&"@/store"), "floor import is not derived");
        assert!(norm.code.contains("import { useAppStore } from \"@/store\";"), "floor stays in code");

        // migrate the NORMALIZED code, then re-render through the emitter → the normalized code back.
        let (body, specs) = migrate_code(&norm.code);
        let fmt: Vec<_> = specs.iter().map(to_fmt).collect();
        assert_eq!(
            bsc_record::imports_fmt::body_with_imports(&body, &fmt),
            norm.code,
            "emit(migrate(normalize(code))) must equal normalize(code) BYTE for byte",
        );
        assert_eq!(specs, norm.derived, "the migrated specs are exactly the derived ones");
    }

    #[test]
    fn normalize_is_idempotent() {
        let u = universe();
        let code = "import { renderGraph } from \"@/features/glance/lib/glanceData\";\n\nrun();\n";
        let once = normalize_code(code, &u).code;
        let twice = normalize_code(&once, &u).code;
        assert_eq!(once, twice, "normalizing normalized code is a no-op");
    }

}
